-- RegiStream database schema.
-- Generated by scripts/supabase/generate.mjs from src/server/data/seed.ts. Do not edit by hand:
-- change the app's types and seed, then regenerate.
--
-- Row Level Security is switched ON for every table with no policies yet, so nothing is readable
-- or writable through the public API until the role policies are added (Phase 2).

create table programs (
  id text primary key,
  code text,
  name text,
  description text,
  program_type text,
  years_to_complete integer,
  is_active boolean,
  created_at timestamptz
);
alter table programs enable row level security;


create table curricula (
  id text primary key,
  program_id text references programs(id),
  code text,
  name text,
  effective_year text,
  is_active boolean,
  created_at timestamptz
);
alter table curricula enable row level security;

create index curricula_program_id_idx on curricula (program_id);

create table subjects (
  id text primary key,
  code text,
  title text,
  description text,
  units numeric,
  lecture_hours numeric,
  lab_hours numeric,
  is_active boolean,
  created_at timestamptz
);
alter table subjects enable row level security;


create table program_subjects (
  id text primary key,
  curriculum_id text references curricula(id),
  subject_id text references subjects(id),
  year_level integer,
  semester_period text,
  is_required boolean,
  prerequisite_subject_ids jsonb,
  prerequisite_standing integer,
  prerequisite_note text,
  excluded_from_gwa boolean
);
alter table program_subjects enable row level security;

create index program_subjects_curriculum_id_idx on program_subjects (curriculum_id);
create index program_subjects_subject_id_idx on program_subjects (subject_id);

create table academic_years (
  id text primary key,
  label text,
  start_date date,
  end_date date,
  is_active boolean
);
alter table academic_years enable row level security;


create table semesters (
  id text primary key,
  academic_year_id text references academic_years(id),
  program_id text references programs(id),
  year_level integer,
  semester_period text,
  start_date date,
  end_date date,
  is_active boolean,
  grades_due_date date
);
alter table semesters enable row level security;

create index semesters_academic_year_id_idx on semesters (academic_year_id);
create index semesters_program_id_idx on semesters (program_id);

create table sections (
  id text primary key,
  code text,
  program_id text references programs(id),
  year_level integer,
  capacity integer,
  is_active boolean,
  created_at timestamptz
);
alter table sections enable row level security;

create index sections_program_id_idx on sections (program_id);

create table faculty (
  id text primary key,
  employee_id text,
  first_name text,
  last_name text,
  diploma text,
  position text,
  is_head boolean,
  email text,
  contact_number text,
  is_active boolean,
  created_at timestamptz
);
alter table faculty enable row level security;


create table students (
  id text primary key,
  address_region text,
  address_province text,
  address_city_municipality text,
  address_barangay text,
  address_district text,
  address_street text,
  birth_region text,
  birth_province text,
  birth_city_municipality text,
  blood_type text,
  employment_status text,
  disability text,
  disability_specify text,
  social_media text,
  social_media_account text,
  emergency_contact_last_name text,
  emergency_contact_first_name text,
  emergency_contact_middle_name text,
  emergency_contact_relationship text,
  emergency_contact_number text,
  emergency_contact_address text,
  student_number text,
  first_name text,
  middle_name text,
  last_name text,
  extension_name text,
  email text,
  contact_number text,
  address text,
  birth_date date,
  birth_place text,
  sex text,
  civil_status text,
  nationality text,
  highest_education text,
  classification text,
  scholarship_type text,
  learner_id text,
  applicant_standing text,
  reference_code text,
  drive_folder_id text,
  secondary_school text,
  secondary_school_year_attended text,
  basis_of_admission text,
  date_admitted date,
  nstp_serial_no text,
  graduated_at timestamptz,
  departure_reason text,
  departure_note text,
  departed_at timestamptz,
  special_order_no text,
  program_id text references programs(id),
  curriculum_id text references curricula(id),
  section_id text references sections(id),
  year_level integer,
  status text,
  is_transferee boolean,
  rejection_reason text,
  approved_at timestamptz,
  archived_at timestamptz,
  created_at timestamptz,
  updated_at timestamptz
);
alter table students enable row level security;

create index students_program_id_idx on students (program_id);
create index students_curriculum_id_idx on students (curriculum_id);
create index students_section_id_idx on students (section_id);

create table users (
  id text primary key,
  status text,
  must_change_password boolean,
  failed_login_attempts integer,
  locked_until timestamptz,
  last_login_at timestamptz,
  created_at timestamptz,
  updated_at timestamptz,
  email text,
  first_name text,
  last_name text,
  title text,
  position text,
  role text,
  faculty_id text references faculty(id),
  student_id text references students(id),
  auth_user_id uuid unique references auth.users(id) on delete set null
);
alter table users enable row level security;

create index users_faculty_id_idx on users (faculty_id);
create index users_student_id_idx on users (student_id);

create table class_schedules (
