  days jsonb,
  start_time text,
  end_time text,
  room text,
  status text,
  created_at timestamptz,
  updated_at timestamptz
);
alter table class_schedules enable row level security;

create index class_schedules_semester_id_idx on class_schedules (semester_id);
create index class_schedules_subject_id_idx on class_schedules (subject_id);
create index class_schedules_section_id_idx on class_schedules (section_id);
create index class_schedules_faculty_id_idx on class_schedules (faculty_id);

create table faculty_assignments (
  id text primary key,
  faculty_id text references faculty(id),
  class_schedule_id text references class_schedules(id),
  assigned_at timestamptz
);
alter table faculty_assignments enable row level security;

create index faculty_assignments_faculty_id_idx on faculty_assignments (faculty_id);
create index faculty_assignments_class_schedule_id_idx on faculty_assignments (class_schedule_id);

create table grade_deadline_overrides (
  id text primary key,
  semester_id text references semesters(id),
  subject_id text references subjects(id),
  batch text,
  class_schedule_id text references class_schedules(id),
  due_date date,
  created_by_user_id text,
  created_at timestamptz
);
alter table grade_deadline_overrides enable row level security;

create index grade_deadline_overrides_semester_id_idx on grade_deadline_overrides (semester_id);
create index grade_deadline_overrides_subject_id_idx on grade_deadline_overrides (subject_id);
create index grade_deadline_overrides_class_schedule_id_idx on grade_deadline_overrides (class_schedule_id);

create table enrollments (
