  total_units numeric,
  remarks text,
  scholarship text,
  grades_viewed_at timestamptz,
  grades_viewed_signature text
);
alter table enrollments enable row level security;

create index enrollments_student_id_idx on enrollments (student_id);
create index enrollments_semester_id_idx on enrollments (semester_id);

create table enrollment_subjects (
  id text primary key,
  enrollment_id text references enrollments(id),
  subject_id text references subjects(id),
  class_schedule_id text references class_schedules(id),
  units numeric,
  excluded_from_gwa boolean,
  enrolled_at timestamptz,
  final_percentage numeric,
  final_grade text,
  completion_grade text,
  completion_percentage numeric,
  grade_status text,
  graded_at timestamptz,
  graded_by_user_id text
);
alter table enrollment_subjects enable row level security;

create index enrollment_subjects_enrollment_id_idx on enrollment_subjects (enrollment_id);
create index enrollment_subjects_subject_id_idx on enrollment_subjects (subject_id);
create index enrollment_subjects_class_schedule_id_idx on enrollment_subjects (class_schedule_id);

